/* @socom-skeleton stub Create__9CSealUnitFUi */
CSealUnit * CSealUnit::Create(unsigned int num)
{
	/* 0x2d7620: the unit with that number, made (and appended to m_list) when missing; unit
	 * 24 gets the multiplayer radio channel valve, every other one none */
	CSealUnit* unit = GetUnitByTeam(num);

	if (unit == NULL)
	{
		unit = new CSealUnit(num);
		m_list.push_back(unit);
	}

	unit->m_radio_channel_valve = num == 24 ? CValve::Create("mp_radio_channel_valve", (VALVE_TYPE)1) : NULL;
	return unit;
}

/* @socom-skeleton stub GetUnitByTeam__9CSealUnitFUi */
CSealUnit * CSealUnit::GetUnitByTeam(unsigned int team)
{
	/* 0x2d7590: the unit with that number */
	for (std::list<CSealUnit*>::iterator it = m_list.begin(); it != m_list.end(); ++it)
	{
		if ((*it)->m_unit_num == team)
			return *it;
	}

	return NULL;
}

/* @socom-skeleton stub GetMyLookDir__9CSealUnitFP6CPnt3DP6CPnt3DP10CZSealBody */
void CSealUnit::GetMyLookDir(CPnt3D *out, CPnt3D *dir, CZSealBody *seal)
{
	/* 0x2d7340 (FollowTick, OnCommand HOLDPOS): where a member watches. In an ambush the
	 * ambush direction; behind the player Bravo's first seal 45 degrees left, its second 90
	 * degrees left, Able's second 45 degrees right (the first along `dir`, keeping its y);
	 * behind another seal a pair splits 60 degrees each way, a single one looks along dir */
	if (m_ambush)
	{
		*out = m_ambush_dir;
		return;
	}

	*out = *dir;
	const f32 c45 = 0.7071f;
	const f32 c60 = 0.5f;
	const f32 s60 = 0.866f;

	if (m_follow_source == ftsGetPlayer())
	{
		if (m_unit_num == 3)
		{
			if (FrontSeal() == seal)
			{
				out->x = c45 * dir->x - c45 * dir->z;
				out->y = 0.0f;
				out->z = c45 * dir->x + c45 * dir->z;
			}
			else
			{
				out->x = -dir->z;
				out->y = 0.0f;
				out->z = dir->x;
			}
		}
		else if (FrontSeal() != seal)
		{
			out->x = c45 * dir->x + c45 * dir->z;
			out->y = 0.0f;
			out->z = -c45 * dir->x + c45 * dir->z;
		}
	}
	else if (m_seals.size() == 2)
	{
		if (FrontSeal() == seal)
		{
			out->x = c60 * dir->x - s60 * dir->z;
			out->y = 0.0f;
			out->z = s60 * dir->x + c60 * dir->z;
		}
		else
		{
			out->x = c60 * dir->x + s60 * dir->z;
			out->y = 0.0f;
			out->z = -s60 * dir->x + c60 * dir->z;
		}
	}
	else
	{
		out->x = dir->x;
		out->y = 0.0f;
		out->z = dir->z;
	}
}

/* @socom-skeleton stub can_run_anim__FPCc */
CZAnim * can_run_anim(const char *name)
{
	/* @socom-skeleton stub run_once$2378 */
	static unsigned char run_once = 1;

	/* 0x2d72c0 (inline in AllowCommand): the anim when it is ready (state 1), or - never,
	 * run_once stays set - finished (5) */
	CZAnim *anim = ZAnim.GetAnim(name, NULL);

	if (anim == NULL)
		return NULL;

	if (anim->m_state == 1 || (!run_once && anim->m_state == 5))
		return anim;

	return NULL;
}

/* @socom-skeleton stub AllowCommand__9CSealUnitFP10CZSealBody10FT_COMMANDPv */
bool CSealUnit::AllowCommand(CZSealBody *source, FT_COMMAND cmd, void *data)
{
	/* 0x2d6bf0 (the orders menu's filter): the fireteam (1) asks Bravo (3) about the orders
	 * only Bravo takes (HOLDPOS, ESCORT, the moving orders but GOTONODE, COVERTARGET, AMBUSH).
	 * Network: the radio / message teams (24, 25, 26, 30, 31) allow anything to a living
	 * source. Else a member's control decides (the first that allows), then: BOMB while the
	 * air support anim is ready (state 1); EXTRACT while the extraction anim is ready and a
	 * rescued escortee stands in the source's extraction region (type 1); AMBUSH when the unit
	 * has seals; any other order when a member or a sub-unit allows it, or (the escortee unit)
	 * a restrained escortee of another unit at the source's reticle. ELF quirks kept: the
	 * members' answer is not used for BOMB / EXTRACT / AMBUSH; a missing Bravo / escortee unit
	 * is not NULL-tested */
	bool allow = false;

	if (m_unit_num == 1)
	{
		switch (cmd)
		{
		case CMD_HOLDPOS:
		case CMD_ESCORT:
		case CMD_ATTACKTO:
		case CMD_RUNTO:
		case CMD_STEALTHTO:
		case CMD_LEADTO:
		case CMD_COVERTARGET:
		case CMD_AMBUSH:
		{
			CSealUnit *bravo = NULL;

			for (std::list<CSealUnit *>::iterator i = m_list.begin(); i != m_list.end(); ++i)
			{
				if ((*i)->m_unit_num == 3)
				{
					bravo = *i;
					break;
				}
			}

			return bravo->AllowCommand(source, cmd, data);
		}

		default:
			break;
		}
	}

	if (theNetwork.m_bNetwork)
	{
		u32 num = m_unit_num;

		if (num - 25 < 2 || num - 30 < 2 || num == 24)
		{
			if (source->m_isAlive)
				return true;
		}
	}

	for (std::list<CZSealBody *>::iterator i = m_seals.begin(); i != m_seals.end() && !allow; ++i)
	{
		CSealCtrl *ctrl = *i != NULL ? static_cast<CSealCtrl *>((*i)->m_control) : NULL;
		allow = ctrl != NULL ? ctrl->AllowCommand(source, cmd, data) : false;
	}

	switch (cmd)
	{
	case CMD_EXTRACT:
	{
		if (can_run_anim("escortee_extract") == NULL)
			return false;

		CAiMap::region *region = AiMaps.GetRegionTypeContainer((CAiMap::region::TYPE)1, source->m_mapLocValid);

		if (region == NULL)
			return false;

		CSealUnit *escortees = NULL;

		for (std::list<CSealUnit *>::iterator i = m_list.begin(); i != m_list.end(); ++i)
		{
			if ((*i)->m_unit_num == 17)
			{
				escortees = *i;
				break;
			}
		}

		for (std::list<CZSealBody *>::iterator i = escortees->m_seals.begin(); i != escortees->m_seals.end(); ++i)
		{
			CZSealBody *seal = *i;

			if (seal == NULL)
				continue;

			CSealCtrlAi *ai = static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi();

			/* 0x2d715c: a rescued escortee standing in the region allows it */
			if (ai != NULL && ai->AiStateIs(STATE_RESCUED) && region->Contains(seal->m_mapLocValid))
				return true;
		}

		return false;
	}

	case CMD_BOMB:
		return can_run_anim("team_airsupport") != NULL;

	case CMD_AMBUSH:
		return !m_seals.empty();

	default:
		break;
	}

	for (std::list<CSealUnit *>::iterator i = m_sub_units.begin(); i != m_sub_units.end() && !allow; ++i)
		allow = (*i)->AllowCommand(source, cmd, data);

	if (allow)
		return true;

	if (m_unit_num == 17)
	{
		CZSealBody *target = source->GetReticuleSeal();

		if (target != NULL && (target->m_team & 0x20000))
		{
			CSealCtrl *ctrl = static_cast<CSealCtrl *>(target->m_control);

			if (ctrl != NULL && ctrl->m_unit != this)
				allow = ctrl->AllowCommand(source, cmd, data);
		}
	}

	return allow;
}

