/* @socom-skeleton stub InitalizeSealUnit__9CSealUnitFP10CZSealBody */
void CSealUnit::InitalizeSealUnit(CZSealBody *seal)
{
	/* 0x2d4250 (CreateSinglePlayerUnits, CSpawners::Tick): the seal joins the unit of its
	 * team: bit 8 Bravo (3), bit 4 Able (2), 0x10000000 unit 28, 0x20000 the escortees (17),
	 * the first of bits 5..15 that unit, else unit 4. SealJoinUnit is inlined each time; the
	 * unit (GetUnitByTeam inlined) is not NULL-tested. */
	if (seal == NULL)
		return;

	u32 team = seal->m_team;

	if (team & 8)
		GetUnitByTeam(3)->SealJoinUnit(seal);
	else if (team & 4)
		GetUnitByTeam(2)->SealJoinUnit(seal);
	else if (team & 0x10000000)
		GetUnitByTeam(28)->SealJoinUnit(seal);
	else if (team & 0x20000)
		GetUnitByTeam(17)->SealJoinUnit(seal);
	else
	{
		bool joined = false;

		for (u32 bit = 5; bit < 16; bit++)
		{
			if ((seal->m_team & (1u << bit)) && !joined)
			{
				GetUnitByTeam(bit)->SealJoinUnit(seal);
				joined = true;
			}
		}

		if (!joined)
			GetUnitByTeam(4)->SealJoinUnit(seal);
	}
}

/* @socom-skeleton stub CreateSinglePlayerUnits__9CSealUnitFv */
void CSealUnit::CreateSinglePlayerUnits()
{
	/* 0x2d3750 (CMission::Open, ReOpen_Load): the fireteam (1) with Able (2) and Bravo (3)
	 * under it, units 28, 17 (escortees), 4 (the enemies, with 5..15 under it) and 29
	 * (support), all Create inlined; every seal joins its unit; then the fireteam is told to
	 * hold fire and given the mission's fireteam order (theMission ai params, default
	 * FOLLOW) - with HOLDPOS Bravo holds (option 8: no look) and Able follows. */
	CSealUnit* fireteam = Create(1);
	CSealUnit* able = Create(2);
	CSealUnit* bravo = Create(3);
	Create(28);
	Create(17);
	CSealUnit* enemies = Create(4);
	Create(29);

	fireteam->m_sub_units.push_back(able);
	able->m_parent = fireteam;
	fireteam->m_sub_units.push_back(bravo);
	bravo->m_parent = fireteam;

	/* Bravo's compass anchor (type 8, "BRAVOTEAM"), once */
	if (bravo->m_compassanchor == NULL)
	{
		CCompassAnchor* anchor = CCompass::CreateAnchor(CPnt3D::zero, "BRAVOTEAM");
		anchor->m_type = 8;
		bravo->m_compassanchor = anchor;
	}


	for (u32 num = 5; num < 16; num++)
	{
		CSealUnit* unit = Create(num);
		enemies->m_sub_units.push_back(unit);
		unit->m_parent = enemies;
	}

	for (std::list<CEntity*>::iterator it = CEntity::m_list.begin(); it != CEntity::m_list.end(); ++it)
	{
		CEntity* entity = *it;
		InitalizeSealUnit(entity != NULL && entity->m_type == 2 ? static_cast<CZSealBody *>(entity) : NULL);
	}

	CZSealBody* player = ftsGetPlayer();
	fireteam->IssueCommand(player, CMD_HOLDFIRE, NULL, true);
	FT_COMMAND order = theMission.m_ai_params.fireteam_command;

	if (order == CMD_HOLDPOS)
	{
		bravo->IssueCommand(player, CMD_HOLDPOS, (void *)8, true);
		able->IssueCommand(player, CMD_FOLLOW, NULL, true);
	}
	else
		fireteam->IssueCommand(player, order, NULL, true);

	m_created_units_test = 1;
#ifdef SOCOM_PORT
	for (std::list<CSealUnit*>::iterator it = m_list.begin(); it != m_list.end(); ++it)
	{
		CSealUnit* unit = *it;

		if (!unit->m_seals.empty() || !unit->m_escortees.empty())
			SOCOM_PORT_TRACE("UNIT: %d: %d seals (%s ...), %d escortees, order %d", unit->m_unit_num, (int)unit->m_seals.size(),
				unit->m_seals.empty() ? "-" : unit->m_seals.front()->m_node->m_name, (int)unit->m_escortees.size(), (int)unit->FrontCommand());
	}
#endif
}

/* @socom-skeleton stub AddBreachMember__FP10CAiSBreachP11CSealCtrlAi */
void AddBreachMember(CAiSBreach *breach, CSealCtrlAi *ai)
{
	/* 0x2d3540 (OnCommand's breach orders): the AI pushes STATE_BREACH filled from the unit's
	 * template. The first member leads (and a new count valve is made), the second opens
	 * (also in the leader's state); each takes the next stack place and adds one to the count
	 * of members still on their way */
	if (!ai->PushAiState(STATE_BREACH, true))
		return;

	CAiState *top = ai->GetAiState();
	CAiSBreach *state = top->m_state == STATE_BREACH ? static_cast<CAiSBreach *>(top) : NULL;

	if (state == NULL) /* port: NULL-tested (ELF writes through it) */
		return;

	*state = *breach;

	if (state->m_leader == NULL)
	{
		state->m_opener = ai;
		state->m_leader = ai;
		breach->m_opener = ai;
		breach->m_leader = ai;
		state->m_count = CValve::Create(NULL, 0, VALVE_TYPE::VTYPE_TEMP);
		breach->m_count = state->m_count;
		state->m_index = 0;
		breach->m_index = 0;
	}
	else if (state->m_leader == state->m_opener)
	{
		state->m_opener = ai;
		breach->m_opener = ai;
		CAiState *lead = state->m_leader->GetAiState();

		if (lead->m_state == STATE_BREACH)
			static_cast<CAiSBreach *>(lead)->m_opener = ai;
	}

	state->m_index = breach->m_index++;
	CValve *count = state->m_count;
	u32 value = count->m_value + 1;
	u32 change = count->m_value == value ? 0 : (value != 0 ? 1 : 2);
	count->m_value = value;

	if (change != 0)
		count->MakeCallbacks((VALVE_STATE)change);

	state->m_setup = 1;
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("BREACH: %s joins (place %u, leader %s, opener %s, %u on the way)", ai->m_entity->m_node->m_name,
		state->m_index, state->m_leader->m_entity->m_node->m_name, state->m_opener->m_entity->m_node->m_name, (u32)count->m_value);
#endif
}

/* @socom-skeleton stub SetFormation__9CSealUnitFP10CZSealBodyP6CPnt3D */
CZSealBody * CSealUnit::SetFormation(CZSealBody *source, CPnt3D *offset)
{
	/* @socom-skeleton stub Xoff$2886 */
	static float Xoff = 25.0f;
	/* @socom-skeleton stub Zoff$2889 */
	static float Zoff = -25.0f;
	/* @socom-skeleton stub UoffMult$2892 */
	static float UoffMult = 1.5f;
	/* @socom-skeleton stub EoffMult$2895 */
	static float EoffMult = 1.0f;

	/* 0x2d31d0 (IssueCommand FOLLOW): every member but the source follows it at the running
	 * offset (from `offset`, else (Xoff, 0, Zoff)): each seal one step further out to its
	 * side and back; the escortees (after the first seal) one step inside; each sub-unit
	 * after the first member a wider step (UoffMult) to the other side, going on from where
	 * the sub-unit left the offset. The offset reached is written back. */
	m_follow_source = source;
	bool escortees = !m_escortees.empty();
	CPnt3D off(Xoff, 0.0f, Zoff);

	if (offset != NULL)
		off = *offset;

	bool first = true;

	for (std::list<CZSealBody*>::iterator it = m_seals.begin(); it != m_seals.end(); ++it)
	{
		CZSealBody* seal = *it;

		if (seal != source)
		{
			seal->IssueCommand(source, CMD_FOLLOW, &off, true);
			off.x = off.x < 0.0f ? off.x - Xoff : off.x + Xoff;
			off.z = off.z + Zoff;
		}

		if (escortees)
		{
			f32 x = off.x;

			for (std::list<CZSealBody*>::iterator e = m_escortees.begin(); e != m_escortees.end(); ++e)
			{
				off.x = off.x - Xoff;
				off.z = off.z - Zoff * (1.0f - EoffMult);
				(*e)->IssueCommand(source, CMD_FOLLOW, &off, true);
				off.x = off.x + Xoff;
				off.z = off.z + Zoff;
			}

			off.x = x;
			escortees = false;
		}

		first = false;
	}

	for (std::list<CSealUnit*>::iterator it = m_sub_units.begin(); it != m_sub_units.end(); ++it)
	{
		if (!first)
		{
			off.z = off.z + Zoff * UoffMult;
			off.x = off.x < 0.0f ? Xoff * UoffMult : -Xoff * UoffMult;
		}

		(*it)->IssueCommand(source, CMD_FOLLOW, &off, true);
		first = false;
	}

	if (offset != NULL)
		*offset = off;

	return source;
}

/* @socom-skeleton stub VoiceHandSignal__9CSealUnitFP10CZSealBody10FT_COMMANDPvb */
void CSealUnit::VoiceHandSignal(CZSealBody *source, FT_COMMAND cmd, void *, bool)
{
	/* 0x2d2f40 (IssueCommand, before the order is recorded): the source gives the order's
	 * hand signal - the moving orders and FOLLOW (unless the last order was FOLLOW) signal 0,
	 * HOLDPOS 1, FIREATWILL 2, LASETARGET / DEPLOY 3; the player signals Bravo only when he
	 * can see its first member. Nothing for a unit without members */
	if (m_seals.empty() || source == NULL)
		return;

	s8 signal = -1;

	switch (cmd)
	{
	case CMD_ATTACKTO:
	case CMD_LEADTO:
	case CMD_RUNTO:
	case CMD_STEALTHTO:
		signal = 0;
		break;
	case CMD_FIREATWILL:
		signal = 2;
		break;
	case CMD_HOLDPOS:
		signal = 1;
		break;
	case CMD_FOLLOW:
		if (FrontCommand() != CMD_FOLLOW)
			signal = 0;
		break;
	case CMD_LASETARGET:
	case CMD_DEPLOY:
		signal = 3;
		break;
	default:
		break;
	}

	if (signal == -1)
		return;

	CSealCtrl *ctrl = static_cast<CSealCtrl *>(source->m_control);
	bool player = ctrl != NULL && ctrl->IsPlayer();

	if (player && m_unit_num == 3)
	{
		CAiMapLoc from = source->m_mapLocValid;
		CAiMapLoc to = FrontSeal()->m_mapLocValid; /* ELF: the list head is not tested */

		if (!AiMaps.CanSeeLine(from, to, NULL))
			signal = -1;
	}

	if (signal != -1)
		source->DoHandSignal((SEAL_HANDSIGNAL)signal);
}

/* @socom-skeleton stub HandleSupport__9CSealUnitFP10CZSealBody10FT_COMMANDPvb */
void CSealUnit::HandleSupport(CZSealBody *source, FT_COMMAND cmd, void *, bool)
{
	/* 0x2d2bd0 (IssueCommand of the support unit 29): BOMB runs team_airsupport; EXTRACT gives
	 * every rescued escortee (unit 17) standing in the extraction region around the source
	 * the hostage_rescue valve, and runs escortee_extract with that valve */
	if (cmd == CMD_BOMB)
	{
		CZAnim *anim = can_run_anim("team_airsupport");

		if (anim != NULL)
			anim->Activate(NULL);
		return;
	}

	if (cmd != CMD_EXTRACT)
		return;

	CValve *valve = CValve::Create("hostage_rescue", 0, VALVE_TYPE::VTYPE_TEMP);
	CAiMap::region *area = AiMaps.GetRegionTypeContainer((CAiMap::region::TYPE)1, source->m_mapLocValid);

	if (area != NULL)
	{
		CSealUnit *escortees = NULL;

		for (std::list<CSealUnit *>::iterator u = m_list.begin(); u != m_list.end(); ++u)
		{
			if ((*u)->m_unit_num == 17)
			{
				escortees = *u;
				break;
			}
		}

		if (escortees != NULL) /* port: NULL-tested (ELF reads its seals through NULL) */
		{
			for (std::list<CZSealBody *>::iterator i = escortees->m_seals.begin(); i != escortees->m_seals.end(); ++i)
			{
				CZSealBody *seal = *i;
				CSealCtrlAi *ai = seal != NULL ? static_cast<CSealCtrl *>(seal->m_control)->GetSealCtrlAi() : NULL;

				if (ai == NULL || !ai->AiStateIs(STATE_RESCUED) || !area->Contains(seal->m_mapLocValid))
					continue;

				CAiState *top = ai->GetAiState();
				CAiSRescued *rescued = top->m_state == STATE_RESCUED ? static_cast<CAiSRescued *>(top) : NULL;

				if (rescued != NULL) /* port: NULL-tested */
					rescued->SetExtractValve(valve);
			}
		}
	}

	CZAnim *anim = can_run_anim("escortee_extract");

	if (anim != NULL)
	{
		if (valve != NULL)
			anim->ActivateArg(1, 4, valve, 0);
		else
			anim->Activate(NULL);
	}
}

/* @socom-skeleton stub GetUnitNameStringFromUnitNum__FiPc */
void GetUnitNameStringFromUnitNum(int unit, char *out)
{
	/* 0x2d2b10: the radio name of a unit (others: out is left as it is) */
	switch (unit)
	{
	case 1: sprintf(out, "TEAM"); break;
	case 2: sprintf(out, "ABLE"); break;
	case 3: sprintf(out, "BRAVO"); break;
	case 17: sprintf(out, "ESCORTEE"); break;
	case 29: sprintf(out, "SUPPORT"); break;
	default: break;
	}
}

/* @socom-skeleton stub GetSoundNameStringFromCmd__Fi10FT_COMMANDPci */
void GetSoundNameStringFromCmd(int unit, FT_COMMAND cmd, char *out, int leader)
{
	/* 0x2d2730: the confirmation sound of an order: SND_<unit>_<leader handle>_WILL_<order> */
	static const char *const verbs[26] = {
		NULL, "DEFAULT_ACTION", "DEPLOY", "FIREATWILL", "FOLLOW", "HOLDPOS", "HOLDFIRE", "REGROUP",
		"REMOVEKILLS", "AMBUSH", "RESTRAIN", "GETDOWN", "ESCORT", "GOTO", "STEALTHTO", "RUNTO", "LEADTO",
		"ATTACKTO", "BREACHBANGCLEAR", "BREACHFRAGCLEAR", "BREACHNONECLEAR", "BOMB", "EXTRACT",
		"COVERTARGET", "LASETARGET", "CLEARAREA"
	};
	char name[20] = "unknown";
	GetUnitNameStringFromUnitNum(unit, name);
	u32 c = (u8)cmd;

	if (c < 26 && verbs[c] != NULL)
	{
		sprintf(out, "SND_%s_%d_WILL_%s", name, leader, verbs[c]);
		return;
	}

	/* the command's name; ELF quirk: its 5th character (a char, sign-extended) is passed as
	 * the %s argument. port: the name from that character on (past "CMD_") */
	char tmp[80];
	sprintf(tmp, "%s", CSealCtrl::GetCommandName(cmd));
	sprintf(out, "SND_%s_%d_WILL_%s", name, leader, &tmp[4]);
}

